      "coffee.title": "Ta tasse. Ton chemin.",
      "coffee.intro": "Bois un café turc ou arabe, retourne la tasse sur la soucoupe, attends environ une minute – puis montre à DEGAJA ce que le marc révèle.",
      "coffee.howToTitle": "Comment ça marche :",
      "coffee.step1": "Verse une petite tasse d'eau froide (environ 60–70 ml) dans une cafetière turque (cezve).",
      "coffee.step2": "Ajoute une cuillère à café bombée de café turc très finement moulu (et du sucre si tu veux) pendant que l'eau est encore froide, et mélange.",
