      "human.intro": "Parle directement et en toute confidentialité avec notre experte – uniquement par audio, sans vidéo, et sans jamais partager ton numéro de téléphone personnel.",
      "rituale.eyebrow": "✦ RITUELS PERSONNELS ✦",
      "rituale.title": "Un chemin personnel vers la clarté.",
      "rituale.intro": "Si tu souhaites aller plus loin après ta consultation, notre experte peut te recommander un rituel personnel avec des matériaux adaptés – un moment conscient pour ton propre alignement.",
