      "join.eyebrow": "✦ ÚNETE A DEGAJA™ ✦", "join.title": "¿Haces lecturas tú misma, o nos recomiendas?", "join.desc": "Conviértete en asesora independiente en DEGAJA, o gana un 10–40 % de comisión como socio/a recomendándonos.", "join.advisorBtn": "Sé asesora →", "join.partnerBtn": "Sé socio/a →",
      "footer.tagline": "Tu pregunta. Tu camino.",
      "footer.impressum": "Aviso legal", "footer.datenschutz": "Privacidad", "footer.agb": "Términos", "footer.widerruf": "Desistimiento", "footer.kontakt": "Contacto", "footer.faq": "FAQ", "footer.werdeberaterin": "Sé asesora", "footer.werdepartner": "Sé socio/a",
