      "palm.disclaimer": "La lettura della mano è a scopo di intrattenimento e riflessione personale e non sostituisce una consulenza professionale. Questa lettura è generata da DEGAJA AI. La tua foto viene analizzata in tempo reale e non viene conservata in modo permanente.",
      "palm.syntheticQuestion": "Cosa rivela il mio palmo su di me?",
