      "coffee.title": "La tua tazzina. Il tuo cammino.",
      "coffee.intro": "Bevi un caffè turco o arabo, capovolgi la tazzina sul piattino, aspetta circa un minuto – poi mostra a DEGAJA cosa rivelano i fondi.",
      "coffee.howToTitle": "Come funziona:",
      "coffee.step1": "Versa una tazzina d'acqua fredda (circa 60–70 ml) in un bricco per caffè turco (cezve).",
      "coffee.step2": "Aggiungi un cucchiaino colmo di caffè turco macinato molto fine (e zucchero se vuoi) mentre l'acqua è ancora fredda, e mescola.",
      "coffee.step3": "Scalda lentamente a fuoco basso senza mescolare di nuovo, finché non si forma una schiuma scura – togli dal fuoco appena prima che trabocchi.",
      "coffee.step4": "Versalo con cura nella tazzina e bevilo finché non rimane solo l'ultimo sorso con i fondi.",
      "coffee.step5": "Capovolgi la tazzina sul piattino e aspetta circa un minuto.",
      "coffee.step6": "Scatta una foto chiara dell'interno della tazzina e caricala qui sotto.",
      "coffee.freeNote": "La tua prima lettura dei fondi di caffè è gratuita.",
