      "rituale.btn": "Узнать больше →",
      "rituale.note1": "Ритуалы — это личные/духовные предложения для ориентира и размышления. Они не гарантируют определённого эффекта или результата. DEGAJA и её консультанты никогда не утверждают, что произойдёт конкретное негативное событие, если ритуал не будет приобретён.",
