      "partner.meta.title": "Стати партнером – DEGAJA",
      "partner.meta.description": "Станьте партнером DEGAJA: діліться своїм персональним посиланням і отримуйте 10–40% комісії з кожного замовлення, оформленого через вас — без сайту й технічних налаштувань.",
