      "join.eyebrow": "✦ DEGAJA™に参加する ✦", "join.title": "自分で鑑定をする、それとも私たちを紹介する?", "join.desc": "DEGAJAでフリーランスのアドバイザーになるか、紹介することでパートナーとして10〜40%のコミッションを得ることができます。", "join.advisorBtn": "アドバイザーになる →", "join.partnerBtn": "パートナーになる →",
