      "footer.disclaimer": "DEGAJAは個人的なガイダンスと娯楽を目的としており、専門家の助言の代わりにはなりません。自動鑑定はAIシステムによって生成されます。",
      "footer.age18": "DEGAJAは18歳以上の方のみを対象としています。",
      "legal.impressumTitle": "法的表記",
      "legal.impressum": "<strong>提供者情報(ドイツ法上の表記義務)</strong><br>Sagacitas Ltd<br>136 Capel Street<br>Dublin D01 T2C9, Ireland<br><br>会社登録番号(アイルランド会社登記局):827800<br><br>連絡先: <a href=\"mailto:info@degaja.com\">info@degaja.com</a><br><br>取締役: Yoel Etel<br><br>コンテンツ責任者: Yoel Etel、住所は上記の通り。",
      "legal.widerrufTitle": "撤回権",
      "legal.widerruf": "<strong>撤回権</strong><br>消費者は通常、理由を述べることなく14日以内に契約を撤回する権利があります。<br><br><strong>デジタル鑑定に関する早期失効</strong><br>購入前に、即時に提供を開始すること、およびそれにより撤回権を失うことに明示的に同意した場合、デジタル鑑定の提供を開始した時点で撤回権は早期に失効します。この同意は、すべての購入前にチェックボックスを通じて明示的に取得されます。<br><br><strong>ライブ相談</strong><br>個人的なオーディオ相談にも同様の規定が適用されます:撤回期間が満了する前に即時開始への明示的な同意がある場合、相談が完全に実施された時点で撤回権は消滅します。<br><br><strong>まだ開始されていないサービス</strong><br>提供がまだ開始されていないサービスを購入した場合、契約から14日以内に、例えば<a href=\"mailto:info@degaja.com\">info@degaja.com</a>へのメールにより、形式を問わず撤回することができます。<br><br><strong>注記</strong><br>この通知は一般的な情報提供を目的としており、個別の法的助言に代わるものではありません。",
      "legal.datenschutzTitle": "プライバシーポリシー",
      "legal.datenschutz": "<strong>1. データ管理者</strong><br>Sagacitas Ltd、136 Capel Street、ダブリン、アイルランド(会社登録番号:827800)。連絡先: <a href=\"mailto:info@degaja.com\">info@degaja.com</a><br><br><strong>2. 処理するデータ</strong><br>アカウント作成時に提供される情報(名前、メールアドレス)は、お使いのブラウザにローカルにのみ保存され、当社に送信・保存されることはありません。サービス提供のために、あなたの質問とDEGAJAが生成する回答を処理します。決済データ(決済代行会社によってのみ処理され、カード情報は当社では保存しません)。言語設定などの技術情報も、お使いのブラウザにローカルに保存されます。<br><br><strong>3. 法的根拠</strong><br>契約の履行(GDPR第6条1項b号)、正当な利益(GDPR第6条1項f号、例:不正防止)、および音声再生などの任意機能に対する同意(GDPR第6条1項a号)。<br><br><strong>4. 第三者プロバイダー(データ処理者)</strong><br>当社は、決済処理、AIによる回答生成、任意の音声合成、内部通知、ホスティングのために、厳選された外部プロバイダーと提携しています。これらのプロバイダーの一部はEU域外(主に米国)に所在しており、データ移転は欧州委員会の標準契約条項に基づいています。<br><br><strong>5. 保存期間</strong><br>当社は、記載された目的に必要な期間、または法律で義務付けられている期間のみデータを保持します。<br><br><strong>6. あなたの権利</strong><br>あなたには、データへのアクセス、訂正、削除、処理の制限、ポータビリティ、および処理への異議申し立ての権利があります。これらのリクエストについては<a href=\"mailto:info@degaja.com\">info@degaja.com</a>までご連絡ください。また、データ保護当局(アイルランドではデータ保護委員会)に苦情を申し立てる権利もあります。<br><br><strong>7. クッキー/ローカルストレージ</strong><br>当社は、例えば言語設定を記憶するために、お使いのブラウザでlocalStorageを使用しています。広告目的の追跡クッキーは使用していません。<br><br><strong>8. 年齢制限</strong><br>DEGAJAは18歳以上の方のみを対象としています。<br><br><strong>9. 変更</strong><br>当社は必要に応じてこのプライバシーポリシーを更新することがあります。最新版は常にこのページでご確認いただけます。",
      "legal.agbTitle": "利用規約",
      "legal.agb": "<strong>1. 適用範囲</strong><br>本規約は、アイルランド・ダブリンのSagacitas Ltdが運営するDEGAJAのウェブサイトおよびサービスの利用に適用されます。<br><br><strong>2. サービスの性質</strong><br>DEGAJAは、娯楽目的でタロット、占星術、数秘術を通じたパーソナルガイダンスを提供します。当社のコンテンツは、専門的な医療、法律、財務、または心理的な助言に代わるものではなく、将来の出来事を保証する予測を構成するものでもありません。個人的な会話の中でアドバイザーが推薦する儀式は、保証された効果のない任意のパーソナル/スピリチュアルな提供物です。DEGAJAおよびそのアドバイザーは、儀式を購入しない場合に特定の悪い出来事が起こると主張することは決してありません。<br><br><strong>3. 年齢制限</strong><br>本サービスの利用は18歳以上の方に限定されます。<br><br><strong>4. 契約の成立とサービス</strong><br>鑑定またはパッケージの購入により、その特定のデジタルサービスの提供に関する契約が成立します。範囲は購入時点でウェブサイトに記載されている通りです。<br><br><strong>5. 価格と支払い</strong><br>特に記載がない限り、すべての価格には適用される税金が含まれています。支払いは決済代行会社を通じて処理されます。<br><br><strong>6. デジタルコンテンツの撤回権</strong><br>これは購入時に即座に提供されるデジタルコンテンツであるため、あなたが即時履行に明示的に同意し、それにより撤回権を失うことを認識した時点で、法定の撤回権は終了します(消費者権利に関するEU指令2011/83/EUに準拠)。<br><br><strong>7. 責任の制限</strong><br>当社は、DEGAJAを通じて受け取ったコンテンツに基づいて行われた決定について責任を負いません。サービスの利用は自己責任で行ってください。<br><br><strong>8. 本規約の変更</strong><br>当社は必要に応じて本規約を更新することがあります。利用時点で公開されているバージョンが適用されます。<br><br><strong>9. 準拠法と管轄</strong><br>アイルランド法が適用されます。法律で認められる範囲で、アイルランド・ダブリンの裁判所が管轄権を有します。<br><br><strong>10. お問い合わせ</strong><br>本規約に関するご質問: <a href=\"mailto:info@degaja.com\">info@degaja.com</a>",
