      "footer.age18": "DEGAJA仅面向年满18周岁及以上的用户。",
      "legal.impressumTitle": "法律声明",
      "legal.impressum": "<strong>提供者信息（根据德国法律要求）</strong><br>Sagacitas Ltd<br>136 Capel Street<br>Dublin D01 T2C9, Ireland<br><br>公司注册号（爱尔兰公司注册处）：827800<br><br>联系方式：<a href=\"mailto:info@degaja.com\">info@degaja.com</a><br><br>董事：Yoel Etel<br><br>内容负责人：Yoel Etel，地址同上。",
      "legal.widerrufTitle": "撤回权",
      "legal.widerruf": "<strong>撤回权</strong><br>消费者通常有权在不说明理由的情况下，于十四天内撤回合同。<br><br><strong>数字解读的提前失效</strong><br>一旦我们开始为你提供数字解读服务，你的撤回权将提前失效，前提是你在购买前已明确同意我们立即开始提供服务，并确认你因此将失去撤回权。我们会在每次购买前通过复选框明确获取此同意。<br><br><strong>实时咨询</strong><br>同样适用于个人语音咨询：在撤回期届满前，若你明确同意立即开始服务，则一旦咨询完全履行完毕，你的撤回权即告失效。<br><br><strong>尚未开始的服务</strong><br>如果你购买的服务尚未开始履行，你可以在签订合同后14天内以非正式方式撤回，例如通过邮件联系<a href=\"mailto:info@degaja.com\">info@degaja.com</a>。<br><br><strong>说明</strong><br>本声明仅供一般性参考，不能替代个别法律咨询。",
      "legal.datenschutzTitle": "隐私政策",
      "legal.datenschutz": "<strong>1. 数据控制者</strong><br>Sagacitas Ltd，136 Capel Street，Dublin，爱尔兰（公司注册号：827800）。联系方式：<a href=\"mailto:info@degaja.com\">info@degaja.com</a><br><br><strong>2. 我们处理哪些数据</strong><br>创建账户时提供的信息（姓名、邮箱）仅存储在你的浏览器本地，绝不会被传输或存储于我们的服务器；你的问题以及DEGAJA生成的回答，用于提供服务；支付数据（仅由我们的支付服务商处理——我们不存储卡片信息）；技术信息，例如你的语言偏好，同样存储在你的浏览器本地。<br><br><strong>3. 法律依据</strong><br>履行合同（GDPR第6(1)(b)条）、合法利益（GDPR第6(1)(f)条，例如防止欺诈），以及对于语音播放等可选功能的同意（GDPR第6(1)(a)条）。<br><br><strong>4. 第三方服务商（数据处理者）</strong><br>我们与经过精心挑选的外部服务商合作，用于支付处理、AI回答生成、可选的语音合成、内部通知以及托管服务。其中部分服务商位于欧盟以外（主要是美国）；数据传输基于欧盟委员会的标准合同条款。<br><br><strong>5. 保留期限</strong><br>我们仅在实现所述目的所必需的期限内保留数据，或依照法律要求保留。<br><br><strong>6. 你的权利</strong><br>你有权访问、更正、删除、限制处理、转移你的数据，并对数据处理提出异议。如需提出任何此类请求，请联系<a href=\"mailto:info@degaja.com\">info@degaja.com</a>。你也有权向数据保护机构投诉（在爱尔兰：数据保护委员会）。<br><br><strong>7. Cookie／本地存储</strong><br>我们在你的浏览器中使用localStorage，例如用于记住你的语言偏好。我们不使用用于广告目的的追踪Cookie。<br><br><strong>8. 年龄限制</strong><br>DEGAJA仅面向年满18周岁及以上的用户。<br><br><strong>9. 变更</strong><br>我们可能会根据需要更新本隐私政策。最新版本始终可在本页面查看。",
      "legal.agbTitle": "条款与条件",
      "legal.agb": "<strong>1. 适用范围</strong><br>本条款适用于DEGAJA网站及服务的使用，该网站与服务由位于爱尔兰都柏林的Sagacitas Ltd运营。<br><br><strong>2. 服务性质</strong><br>DEGAJA通过塔罗、占星和数字命理学提供个人指导，仅供娱乐之用。我们的内容不能替代专业的医疗、法律、财务或心理建议，也不构成对未来事件的保证性预测。顾问在个人对话中推荐的仪式是可选的个人/精神性服务，不保证任何效果；DEGAJA及其顾问从不声称若不购买仪式将发生特定的负面事件。<br><br><strong>3. 年龄限制</strong><br>本服务仅限年满18周岁及以上人士使用。<br><br><strong>4. 合同成立与服务</strong><br>购买一次解读或套餐即构成提供该特定数字服务的合同。服务范围以购买时网站上的描述为准。<br><br><strong>5. 价格与支付</strong><br>除非另有说明，所有价格均含适用税费。支付通过我们的支付服务商处理。<br><br><strong>6. 数字内容的撤回权</strong><br>由于这是购买后立即交付的数字内容，一旦你明确同意立即履行并确认你因此将失去撤回权（依照欧盟2011/83/EU号消费者权益指令），你的法定撤回权即告终止。<br><br><strong>7. 责任限制</strong><br>我们不对基于通过DEGAJA获得的内容而做出的决定承担责任。使用本服务的风险由你自行承担。<br><br><strong>8. 条款变更</strong><br>我们可能会根据需要更新本条款。适用使用时已发布的版本。<br><br><strong>9. 适用法律与管辖权</strong><br>适用爱尔兰法律。在法律允许的范围内，由爱尔兰都柏林法院管辖。<br><br><strong>10. 联系方式</strong><br>如对本条款有任何疑问：<a href=\"mailto:info@degaja.com\">info@degaja.com</a>",
