      "faq.q1": "क्या DEGAJA पर पहली रीडिंग मुफ़्त है?",
      "faq.a1": "हाँ। तुम्हारी पहली टैरो रीडिंग और पहली हस्तरेखा पढ़ाई मुफ़्त है। उसके बाद तुम सिंगल रीडिंग या 3-रीडिंग पैक खरीद सकते हो।",
      "faq.q2": "DEGAJA क्या प्रदान करता है?",
      "faq.a2": "DEGAJA टैरो ओरेकल रीडिंग, AI हस्तरेखा पढ़ाई, ज्योतिष/राशिफल की जानकारी, एक असली सलाहकार के साथ 1:1 लाइव ऑडियो परामर्श, और प्यार, सफलता और संतुलन के लिए व्यक्तिगत अनुष्ठान प्रदान करता है।",
      "faq.q3": "ऑटोमैटिक AI रीडिंग कैसे काम करती है?",
      "faq.a3": "तुम अपना सवाल पूछते हो या अपनी हथेली की फ़ोटो अपलोड करते हो, और DEGAJA तुरंत तुम्हारे लिए एक व्यक्तिगत रीडिंग बनाता है – जो चौबीसों घंटे उपलब्ध है।",
      "faq.q4": "क्या DEGAJA गोपनीय और भरोसेमंद है?",
